'use strict';
const questions=window.QA_SQL_QUESTIONS, notes=window.QA_TUTOR_NOTES, interview=window.QA_INTERVIEW;
const KEY='qa-academy-lesson-v1', $=id=>document.getElementById(id);
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
if(!Array.isArray(questions)||!notes||!interview||questions.some(q=>!notes[q.id]||!interview[q.id]))throw new Error('Нужна полная папка учебного экрана.');
let state={version:1,attempts:[],theme:'light',translations:true,queue:questions.map(q=>q.id),index:0};
let storageOK=true,assisted=false,checked=false;
function contentVersion(a){return Number.isInteger(a.contentVersion)?a.contentVersion:1;}
function validAttempt(a){const q=a&&questions.find(q=>q.id===a.id);return q&&Number.isInteger(a.selected)&&a.selected>=0&&a.selected<q.choices.length&&typeof a.assisted==='boolean'&&typeof a.at==='string';}
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved&&saved.version===1&&Array.isArray(saved.attempts)){state.attempts=saved.attempts.filter(validAttempt);state.theme=saved.theme==='dark'?'dark':'light';state.translations=saved.translations!==false;if(Array.isArray(saved.queue)&&saved.queue.length&&saved.queue.every(id=>questions.some(q=>q.id===id))){state.queue=[...new Set(saved.queue)];state.index=Number.isInteger(saved.index)?Math.max(0,Math.min(saved.index,state.queue.length-1)):0;}}}catch(e){if(!(e instanceof SyntaxError))storageOK=false;}
function showArchiveNotice(){const old=state.attempts.filter(a=>contentVersion(a)!==questions.find(q=>q.id===a.id).version).length;$('content-notice').hidden=!old;$('content-notice').textContent=`Сохранено прежних попыток: ${old}. Они остаются в истории отдельно. Текущие результаты не изменены.`;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){storageOK=false;}$('storage-warning').hidden=storageOK;showArchiveNotice();}
function setTheme(){const dark=state.theme==='dark';document.body.classList.toggle('theme-dark',dark);$('theme').setAttribute('aria-pressed',String(dark));$('theme').textContent=dark?'Светлая тема':'Тёмная тема';}
function current(){return questions.find(q=>q.id===state.queue[state.index]);}
function score(a){return a.selected===questions.find(q=>q.id===a.id).answer?5:0;}
function attemptsFor(id){return state.attempts.filter(a=>a.id===id&&contentVersion(a)===questions.find(q=>q.id===id).version);}
function latest(id){return attemptsFor(id).at(-1);}
function table(columns,rows,caption){const box=el('div',undefined,'table-wrap'),t=el('table'),head=el('thead'),tr=el('tr'),body=el('tbody');t.append(el('caption',caption));columns.forEach(c=>{const th=el('th',c);th.scope='col';tr.append(th);});head.append(tr);t.append(head);rows.forEach(r=>{const row=el('tr');r.forEach(v=>row.append(el('td',String(v))));body.append(row);});t.append(body);box.append(t);if(!rows.length)box.append(el('p','В результате нет товаров: ни один не подходит под указанные условия. Сам запрос выполнен правильно.'));return box;}
function route(view,focus=true){if(!['learn','practice','results'].includes(view))view='learn';for(const name of ['learn','practice','results'])$(name).hidden=name!==view;document.querySelectorAll('[data-view]').forEach(b=>{if(b.dataset.view===view)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');});if(view==='practice')renderQuestion();if(view==='results')renderResults();try{history.replaceState(null,'','#'+view);}catch(e){}if(focus)$('main').focus();}
function updateTranslations(){
 $('translations').checked=state.translations;
 document.querySelectorAll('[data-translation]').forEach(n=>n.hidden=!state.translations);
}
function bilingual(en,ru){
 const box=el('span',undefined,'choice-body'),english=el('span',en,'choice-en');english.lang='en';box.append(english);
 if(en!==ru){const translation=el('span',ru,'translation');translation.dataset.translation='';box.append(translation);}
 return box;
}
function renderQuestion(){
 assisted=false;checked=false;const q=current(),i=interview[q.id];
 $('position').textContent=`Задание ${state.index+1} из ${state.queue.length}`;$('mode').textContent=state.queue.length<questions.length?'Повторение ошибок':'Практика';
 $('progress').max=state.queue.length;$('progress').value=state.index;
 $('question-title').textContent=i.question;$('question-translation').textContent=i.translation;$('question-translation').dataset.translation='';
 $('context-en').textContent=i.context;$('context').textContent=q.context;$('context').dataset.translation='';
 $('task-table').replaceChildren(table(q.columns,q.rows,'products · Test data'));
 $('query').textContent=q.query;$('query-wrap').hidden=!q.query;
 const fs=$('answers');fs.replaceChildren(el('legend','Твой ответ · Your answer'));
 q.displayOrder.forEach(index=>{const label=el('label',undefined,'choice'),input=el('input');input.type='radio';input.name='answer';input.value=String(index);label.append(input,bilingual(i.choices[index],q.choices[index]));fs.append(label);});
 for(const id of ['hint-text','feedback','next','back-explanation','answer-error'])$(id).hidden=true;
 $('feedback').replaceChildren();$('check').disabled=false;$('hint').disabled=false;$('next').textContent=state.index===state.queue.length-1?'Посмотреть результат':'Следующее задание';updateTranslations();
}
function section(title,text){const s=el('section',undefined,'coach-section');s.append(el('h3',title),el('p',text));return s;}
function reinforcement(q){const item=notes[q.id].checkpoint,box=el('section',undefined,'reinforce'),form=el('form'),fs=el('fieldset');box.id='reinforcement';box.append(el('h3','Закрепим · Try another example'),el('p','Похожая задача. Попробуй применить правило — без дополнительных баллов.','small'));const legend=el('legend');legend.append(bilingual(interview[q.id].checkpoint,item.prompt));fs.append(legend);item.choices.forEach((text,i)=>{const label=el('label',undefined,'choice'),input=el('input');input.type='radio';input.name='reinforcement';input.value=String(i);label.append(input,bilingual(interview[q.id].checkpointChoices[i],text));fs.append(label);});const button=el('button','Проверить закрепление'),out=el('p');button.type='submit';out.id='reinforcement-result';out.setAttribute('role','status');form.append(fs,button,out);let submitted=false;form.addEventListener('submit',e=>{e.preventDefault();if(submitted)return;const selected=form.querySelector('input:checked');if(!selected){out.textContent='Выбери вариант, затем проверим его вместе.';return;}const correct=Number(selected.value)===item.answer;out.textContent=(correct?'Верно. ':'Разберём этот пример. ')+item.explain;if(correct){submitted=true;button.disabled=true;form.querySelectorAll('input').forEach(i=>i.disabled=true);}else{button.textContent='Проверить ещё раз';}});box.append(form);return box;}
function interviewAnswer(q){
 const data=interview[q.id],box=el('section',undefined,'interview-answer');box.id='interview-answer';
 box.append(el('h3','Как ответить на собеседовании · Sample answer'));
 const answer=el('p',data.answer,'english');answer.lang='en';box.append(answer);
 const translation=el('p',data.answerRu,'translation');translation.dataset.translation='';box.append(translation);
 const details=el('details');details.append(el('summary','Термины этого вопроса · Key terms'));
 const list=el('dl',undefined,'terms');data.terms.forEach(([term,meaning])=>{const pair=el('div'),label=el('dt',term);label.lang='en';pair.append(label,el('dd',meaning));list.append(pair);});details.append(list);box.append(details);return box;
}
function showFeedback(q,a){const t=notes[q.id],points=score(a),box=$('feedback');box.replaceChildren();const head=el('div',undefined,'feedback-head');head.append(el('h2','Разбор твоего ответа'),el('span',`За выбор ответа: ${points} / 5`,'points'));box.append(head);const own=el('p',undefined,'small');own.append(el('span','Твой ответ · Your answer'),bilingual(interview[q.id].choices[a.selected],q.choices[a.selected]));box.append(own);const model=el('section',undefined,'answer-model');model.append(el('h3','Правильный ответ простыми словами'),el('p',t.model));box.append(model);if(t.observations[a.selected])box.append(section('Что в твоём ответе верно',t.observations[a.selected]));if(t.corrections[a.selected])box.append(section('Что нужно исправить',t.corrections[a.selected]));box.append(el('h3','Решение по шагам'));const steps=el('ol',undefined,'walk');q.steps.forEach(s=>{const li=el('li');li.append(el('span',s));steps.append(li);});box.append(steps,section('Главное, что стоит запомнить',t.remember));const details=el('details');details.append(el('summary','Посмотреть SQL и результат на этих данных'));const pre=el('pre');pre.setAttribute('translate','no');pre.append(el('code',q.verification.sql));details.append(pre,table(q.verification.columns,q.verification.rows,'Ожидаемый результат'),el('p','Сравни выбранные столбцы и строки с условием задания.','small'));const source=el('a','Документация SQLite');source.href=q.source;source.target='_blank';source.rel='noopener noreferrer';details.append(source);box.append(details,interviewAnswer(q),reinforcement(q));const scoring=el('details');scoring.append(el('summary','Как учитывается этот ответ'),el('p','За вопрос с одним верным вариантом начисляется 5 баллов, за другой вариант — 0. Разбор может отметить верную часть выбранного варианта, но это не оценка всего твоего уровня. Задание на закрепление не добавляет баллов.'),el('p',a.assisted?'Использована подсказка. Этот ответ хранится отдельно от самостоятельных.':'Ответ дан без подсказки. Повторное нажатие не добавляет новую попытку.'));box.append(scoring);document.querySelectorAll('#answers input').forEach(input=>{input.disabled=true;const i=Number(input.value),label=input.closest('label');if(i===q.answer){label.classList.add('correct');label.lastChild.append(el('span','Правильный вариант','mark'));}else if(i===a.selected)label.lastChild.append(el('span','Твой вариант — разбор ниже','mark'));});box.hidden=false;$('check').disabled=true;$('hint').disabled=true;$('next').hidden=false;$('back-explanation').hidden=false;updateTranslations();box.focus();}
$('answer-form').addEventListener('submit',e=>{e.preventDefault();if(checked)return;const chosen=document.querySelector('#answers input:checked');if(!chosen){$('answer-error').hidden=false;document.querySelector('#answers input').focus();return;}const selected=Number(chosen.value),q=current();if(!Number.isInteger(selected)||selected<0||selected>=q.choices.length)return;checked=true;$('answer-error').hidden=true;const a={id:q.id,selected,assisted,contentVersion:q.version,presentationVersion:4,translationShown:state.translations,at:new Date().toISOString()};state.attempts.push(a);save();$('progress').value=state.index+1;showFeedback(q,a);});
$('hint').addEventListener('click',()=>{assisted=true;$('hint-text').textContent=current().hint;$('hint-text').hidden=false;$('hint').disabled=true;});
$('next').addEventListener('click',()=>{if(state.index<state.queue.length-1){state.index++;save();renderQuestion();$('main').focus();}else route('results');});
function renderResults(){const done=questions.filter(q=>latest(q.id)),first=questions.filter(q=>{const a=attemptsFor(q.id)[0];return a&&score(a)===5&&!a.assisted;}),wrong=done.filter(q=>score(latest(q.id))<5);$('done-count').textContent=`${done.length} / ${questions.length}`;$('first-count').textContent=`${first.length} / ${questions.length}`;$('summary').textContent=!done.length?'Пока нет ответов. Начни с объяснения.':wrong.length?`Есть ${wrong.length} заданий, к которым стоит вернуться. Разбор и повторение доступны без ограничения времени.`:'Все выполненные задания решены верно. Это результат этого урока, не всей подготовки QA.';$('result-list').replaceChildren();done.forEach(q=>{const a=latest(q.id),li=el('li');li.append(el('b',q.title),el('span',`${score(a)} / 5 · ${a.assisted?'с подсказкой':'без подсказки'} · попыток: ${attemptsFor(q.id).length}`));$('result-list').append(li);});}
$('review').addEventListener('click',()=>{const ids=questions.filter(q=>latest(q.id)&&score(latest(q.id))<5).map(q=>q.id);if(!ids.length){$('summary').textContent='Ошибок для повторения нет. Можно пройти все задания заново.';return;}state.queue=ids;state.index=0;save();route('practice');});
$('again').addEventListener('click',()=>{state.queue=questions.map(q=>q.id);state.index=0;save();route('practice');});
$('reset').addEventListener('click',()=>{if(!confirm('Удалить историю этого урока, включая прежнюю редакцию, в текущем браузере?'))return;state.attempts=[];state.queue=questions.map(q=>q.id);state.index=0;save();renderResults();});
$('translations').addEventListener('change',()=>{state.translations=$('translations').checked;updateTranslations();save();});
$('start').addEventListener('click',()=>route('practice'));$('back-explanation').addEventListener('click',()=>route('learn'));document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>route(b.dataset.view)));$('theme').addEventListener('click',()=>{state.theme=state.theme==='light'?'dark':'light';setTheme();save();});window.addEventListener('hashchange',()=>route(location.hash.slice(1)));$('intro-table').append(table(questions[0].columns,questions[0].rows,'Пример таблицы products'));setTheme();showArchiveNotice();$('storage-warning').hidden=storageOK;$('load-error').hidden=true;route(location.hash.slice(1)||'learn',false);
